import{_ as a,o as s,c as r,a2 as t}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"Security – Change Password","description":"","frontmatter":{"title":"Security – Change Password"},"headers":[],"relativePath":"operations-knowledge-base/presales-support/security-change-password.md","filePath":"operations-knowledge-base/presales-support/security-change-password.md","lastUpdated":1794292919000}'),o={name:"operations-knowledge-base/presales-support/security-change-password.md"};function n(i,e,d,p,c,h){return s(),r("div",null,[...e[0]||(e[0]=[t('<p>The “Change Password” feature allows users to update their account password on the platform. Below is an overview of the feature and how to use it.</p><h2 id="_1-access-path" tabindex="-1">1. Access Path <a class="header-anchor" href="#_1-access-path" aria-label="Permalink to &quot;1. Access Path&quot;">​</a></h2><p>Users can access the password change page through the following path:</p><p>Top-right profile avatar → Security → Change Password</p><p>From this page, users can update their account password.</p><h2 id="_2-operation-guide" tabindex="-1">2. Operation Guide <a class="header-anchor" href="#_2-operation-guide" aria-label="Permalink to &quot;2. Operation Guide&quot;">​</a></h2><h3 id="enter-current-password" tabindex="-1">Enter Current Password <a class="header-anchor" href="#enter-current-password" aria-label="Permalink to &quot;Enter Current Password&quot;">​</a></h3><p>In the “Existing Password” field, enter the password currently used for your account.</p><p>This step verifies your identity before the password is changed.</p><h3 id="set-a-new-password" tabindex="-1">Set a New Password <a class="header-anchor" href="#set-a-new-password" aria-label="Permalink to &quot;Set a New Password&quot;">​</a></h3><p>Enter your new password in the “New Password” field.</p><p>Users can also click the “Generate Password” button, and the system will automatically generate a strong password.</p><p>To improve password security, the platform recommends using a strong password with the following requirements:</p><ul><li>Use both uppercase and lowercase letters</li><li>Include at least one special character, such as #, $, !, %, or &amp;</li><li>Avoid using consecutive characters or simple patterns</li></ul><h3 id="confirm-new-password" tabindex="-1">Confirm New Password <a class="header-anchor" href="#confirm-new-password" aria-label="Permalink to &quot;Confirm New Password&quot;">​</a></h3><p>Re-enter the new password in the “Confirm New Password” field to make sure both entries match and to avoid errors when setting the password.</p><h3 id="save-changes" tabindex="-1">Save Changes <a class="header-anchor" href="#save-changes" aria-label="Permalink to &quot;Save Changes&quot;">​</a></h3><p>After completing and confirming all information, click the “Save Changes” button to finish updating the password.</p><p>If you do not want to continue, click “Cancel.”</p><h2 id="_3-important-notes" tabindex="-1">3. Important Notes <a class="header-anchor" href="#_3-important-notes" aria-label="Permalink to &quot;3. Important Notes&quot;">​</a></h2><h3 id="password-security" tabindex="-1">Password Security <a class="header-anchor" href="#password-security" aria-label="Permalink to &quot;Password Security&quot;">​</a></h3><p>Please make sure your password meets the platform’s strong password requirements. Avoid using simple or easy-to-guess passwords, such as birthdays or consecutive numbers, to protect your account.</p><h3 id="password-consistency" tabindex="-1">Password Consistency <a class="header-anchor" href="#password-consistency" aria-label="Permalink to &quot;Password Consistency&quot;">​</a></h3><p>When entering the new password and confirming it, make sure both entries are exactly the same. Otherwise, the password update will fail.</p><h3 id="password-protection" tabindex="-1">Password Protection <a class="header-anchor" href="#password-protection" aria-label="Permalink to &quot;Password Protection&quot;">​</a></h3><p>After setting a new password, please keep it secure and do not share it with others. The platform uses security measures to protect user accounts, but users should also remain vigilant to prevent unauthorized access.</p><h3 id="regular-password-updates" tabindex="-1">Regular Password Updates <a class="header-anchor" href="#regular-password-updates" aria-label="Permalink to &quot;Regular Password Updates&quot;">​</a></h3><p>To further improve account security, users are advised to change their password regularly, such as every 3 or 6 months, to reduce the risk of password compromise.</p>',28)])])}const w=a(o,[["render",n]]);export{u as __pageData,w as default};
